import * as React from 'react'

// The component brings its own styles, so `gamestage-ui add tag` installs a
// styled Tag rather than a bare span.
import './tag.css'

/**
 * Tag: one short word that says what state a row is in.
 *
 * The MLB leagues list starts each row with Joined, Public or Private
 * (GSUI-400). Nothing in the library fitted. Badge is a reward roundel and
 * Status is the large in-game card (READY, GO!), so until this existed the
 * theme preview drew the word as plain row value text and a reader could not
 * tell a state from a value.
 *
 * It reads its colours from roles every theme already sets, so a new theme
 * draws it with nothing added: `neutral` uses the raised surface and the
 * secondary ink, `positive` the positive ink on the surface, and `accent` the
 * same fill and ink as a primary button. A theme can still set
 * `--gs-tag-fill` and `--gs-tag-ink` to override all three.
 *
 * It is a word, not a control. It takes no handler and has no role, and it
 * never truncates: a translated word wraps rather than losing its end.
 */

/** How much the word stands out. `neutral` is the default. */
export type TagTone = 'neutral' | 'positive' | 'accent'

export interface TagProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** The word. Host copy, always: Joined, Public, Private. */
  label: string
  /** How much it stands out. Defaults to `neutral`. */
  tone?: TagTone
}

export function Tag(props: TagProps) {
  const { label, tone = 'neutral', className, ...rest } = props
  return (
    <span
      {...rest}
      className={['gs-tag', className].filter(Boolean).join(' ')}
      data-gs-component="tag"
      data-gs-tone={tone}
    >
      <span className="gs-tag__label" data-gs-scope="tag" data-gs-part="label">
        {label}
      </span>
    </span>
  )
}

/* Tag. Every value comes from a token; nothing here is a literal colour.

   Each tone sets the two custom properties, and the shape reads only those,
   so a theme that sets --gs-tag-fill and --gs-tag-ink on a scope recolours
   every tone at once. */

.gs-tag {
  --gs-tag-fill-default: var(--gs-color-surface-raised);
  --gs-tag-ink-default: var(--gs-color-ink-secondary);
  --gs-tag-edge-default: var(--gs-color-edge);

  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  max-inline-size: 100%;
  min-inline-size: 0;
  padding: var(--gs-space-1) var(--gs-space-2);

  border: var(--gs-stroke-ui) solid var(--gs-tag-edge, var(--gs-tag-edge-default));
  border-radius: var(--gs-radius-full);
  background: var(--gs-tag-fill, var(--gs-tag-fill-default));
  color: var(--gs-tag-ink, var(--gs-tag-ink-default));
  vertical-align: middle;

  /* A tag sits inside other type, such as a Row value set in the display
     face. Arcade's display shadow then reached the word and blurred it on
     the fill, so the tag sets its own and inherits none. */
  text-shadow: none;
  letter-spacing: normal;
  text-transform: none;
}

.gs-tag[data-gs-tone='positive'] {
  --gs-tag-fill-default: var(--gs-color-surface);
  --gs-tag-ink-default: var(--gs-color-positive-ink, var(--gs-color-positive-solid));
  --gs-tag-edge-default: var(--gs-color-positive-ink, var(--gs-color-positive-solid));
}

.gs-tag[data-gs-tone='accent'] {
  --gs-tag-fill-default: var(--gs-color-interactive);
  --gs-tag-ink-default: var(--gs-color-on-accent);
  --gs-tag-edge-default: var(--gs-color-interactive);
}

/* The word, in the label face at the caption size, so it reads as smaller
   than the row label beside it. It wraps inside itself rather than being cut: a state the
   player can only half read is worse than one on two lines. */
.gs-tag__label {
  min-inline-size: 0;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: var(--gs-type-title-line-height);
  overflow-wrap: anywhere;
}
